// ============================================================================
// MODULE: vigil80_spi_receiver_16to8
// DESCRIPTION: Receives VIGIL80 SPI video stream.     
// Parameters SPI VIGIL80:
// CPOL = 1
// CPHA = 1
// MSB first
//
// VIGIL80 is SPI master:
// - video_sck  generated by camera
// - video_csb  active low, one chip select per frame
// - video_mosi data from camera to FPGA
//
// The first FRAME_PIX words are active image pixels.
// Footer words are discarded.
//
// Each input pixel is 16-bit thermal data.
// Output pixel is 8-bit grayscale.
// ============================================================================

module vigil80_spi_receiver_16to8 #(
    parameter int FRAME_PIX    = 6400,
    parameter int FOOTER_WORDS = 23,
    parameter int TOTAL_WORDS  = FRAME_PIX + FOOTER_WORDS,
    parameter int ADDR_BITS    = $clog2(FRAME_PIX),

    parameter int TEMP_MIN     = 16'd27315,   //Minimum thermal value used as reference for the conversion
    parameter int unsigned TEMP_SHIFT   = 5
)(
    input  logic rst_n,

    input  logic video_sck,
    input  logic video_csb,
    input  logic video_mosi,

    input  logic wr_allow,

    output logic pix_valid,
    output logic [ADDR_BITS-1:0] pix_addr,
    output logic [7:0] pix_data,

    output logic frame_done
);

    localparam int WORD_CNT_BITS = $clog2(TOTAL_WORDS);


    // ========================================================================
    // SPI receiver
    // ========================================================================
    logic [15:0] shift_reg;    //shift register to build up the 16 bits word
    logic [3:0]  bit_cnt;      //to count from 0 to 15

    logic [WORD_CNT_BITS-1:0] word_cnt;  //Count how many 16-bit words have been received in the current frame

    logic frame_active;       // high while CS frame reception is active
    logic capture_enable;     //useful for preventing wr_allow change while saving 

    // =========================================================================
    // 16-bit thermal value to 8-bit grayscale conversion
    //
    // gray = clamp((thermal - TEMP_MIN) >> TEMP_SHIFT)
    //
    // TEMP_MIN and TEMP_SHIFT can be tuned to improve image contrast.
    // =========================================================================

function automatic logic [7:0] thermal16_to_gray8(
    input logic [15:0] thermal
    input logic [15:0] vtemp
);

    logic [15:0] diff;
    logic [15:0] scaled;

    begin

        if (thermal <= 16'd25000) begin

            thermal16_to_gray8 = 8'd0;

        end

        else begin

            diff = thermal - 16'd25000;

            scaled = diff >> 2;

            if (scaled >= 16'd255)
                thermal16_to_gray8 = 8'd255;
            else
                thermal16_to_gray8 = scaled[7:0];

        end

    end

endfunction


    // ========================================================================
    // SPI receiver
    // ========================================================================
    // IMPORTANT:
    // video_csb IS NOT in the sensitivity list.
    //
    // Once a frame has started, CSB is ignored until all 6423 words
    // have been received.
    // ========================================================================
    logic [15:0] completed_word;
    assign completed_word = {shift_reg[14:0], video_mosi};

    logic [15:0] vtemp_reg;

    always_ff @(posedge video_sck or negedge rst_n) begin

        if (!rst_n) begin
            shift_reg <= 16'd0;
            bit_cnt <= 4'd0;
            word_cnt <= '0;

            frame_active <= 1'b0;
            capture_enable <= 1'b0;

            pix_valid <= 1'b0;
            pix_addr <= '0;
            pix_data <= 8'd0;
            frame_done <= 1'b0;
        end
        else begin

            //default value
            pix_valid  <= 1'b0;
            frame_done <= 1'b0;

            // =================================================================
            // WAIT FOR FRAME START
            // =================================================================
            // CSB is used ONLY here.
            // If CSB is high, we simply wait.
            // =================================================================

            if (!frame_active) begin   //If we aren't recording any frames, we can start a new one
                if (!video_csb) begin  //chip selected active
                    // ---------------------------------------------------------
                    // New frame detected
                    // ---------------------------------------------------------
                    frame_active   <= 1'b1;
                    capture_enable <= wr_allow;  //At the beginning of frame,`wr_allow` is copied into `capture_enable`
                                                 //So the decision is made just once at the start of the frame
                                                 //to avoid that changes of wr_allow affects frame’s storage
                    word_cnt       <= '0;

                    // ---------------------------------------------------------
                    // First bit of first 16-bit word
                    // ---------------------------------------------------------
                    shift_reg <= {15'd0, video_mosi};  //first bit loaded into the shift register
                    bit_cnt   <= 4'd1;
                end
            end

            // =================================================================
            // FRAME ACTIVE
            // =================================================================
            // From this point onward CSB is deliberately ignored.
            // This protects the receiver against CSB glitches.
            // =================================================================
            else begin
                // -------------------------------------------------------------
                // Shift next bit
                // -------------------------------------------------------------
                shift_reg <= {shift_reg[14:0], video_mosi};

                // -------------------------------------------------------------
                // Complete 16-bit word
                // -------------------------------------------------------------

                if (bit_cnt == 4'd15) begin
                    bit_cnt <= 4'd0;

                    // =========================================================
                    // ACTIVE IMAGE
                    // =========================================================
                    if (capture_enable) begin
                        if (word_cnt < FRAME_PIX) begin
                            pix_valid <= 1'b1;
                            pix_addr <= word_cnt[ADDR_BITS-1:0];   //save the received pixel at the address corresponding to the number of the received word

                            // Must use concatenation because `shift_reg` would be updated at the end of the loop
                            pix_data <= thermal16_to_gray8(completed_word, vtemp_reg);
                            //pix_data <= completed_word[7:0];
                            //pix_data <= (completed_word > 16'd25000) ? 8'd255 : 8'd0;
                        end
                        else if (word_cnt == FRAME_PIX) begin
                            // Prima parola footer = VTEMP
                            vtemp_reg <= completed_word;
                        end

                        // =========================================================
                        // LAST IMAGE PIXEL
                        // =========================================================
                        if (word_cnt == FRAME_PIX - 1) begin
                            frame_done <= 1'b1;  //After received all the TOTAL_WORDS, set frame_done = 1 only if that frame must be saved
                        end

                    end

                    // =========================================================
                    // END OF COMPLETE FRAME (6400 image words + 23 footer words)
                    // =========================================================

                    if (word_cnt == TOTAL_WORDS - 1) begin
                        word_cnt       <= '0;
                        frame_active   <= 1'b0;
                        capture_enable <= 1'b0;
                    end
                    else begin  //FRAME NOT COMPLETE
                        word_cnt <= word_cnt + 1'b1;
                    end

                end

                // -------------------------------------------------------------
                // Word not complete
                // -------------------------------------------------------------

                else begin
                    bit_cnt <= bit_cnt + 1'b1;
                end

            end
        end
    end

endmodule